-- =============================================================================
-- SISTEMA DE GESTIÓN INTEGRAL PARA CENTROS GERIÁTRICOS (SAMANYA OS)
-- SCRIPT DE CREACIÓN DE BASE DE DATOS RELACIONAL - ORACLE DATABASE
-- =============================================================================
-- Prefijo de tablas: SMY_
-- Estándar: Oracle 11g / 12c / 19c / 21c / 23c
-- Reglas de Nomenclatura y Arquitectura:
--  1. Todas las tablas poseen 'ID NUMBER(10)' como Clave Primaria poblada
--     automáticamente mediante Secuencias y Triggers BEFORE INSERT.
--  2. Todas las llaves foráneas inician obligatoriamente con 'ID_' (ej. ID_ROL, ID_USUARIO, ID_RESIDENTE).
--  3. Todos los estados y opciones categóricas poseen tablas maestras foráneas (SMY_ESTADOS_*, SMY_TIPOS_*, etc.).
--  4. Todas las fechas por defecto registran la hora legal de Bogotá, Colombia (UTC-5):
--     DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE).
--  5. Todas las tablas contienen 'FECHA_CREACION DATE' e 'ID_USUARIO_ULTIMA_MODIFICACION NUMBER(10)'.
--  6. Campos booleanos se manejan como CHAR(1) con validación ('S', 'N').
-- =============================================================================

-- =============================================================================
-- SECCIÓN 0: NÚCLEO MULTI-TENANCY Y CATÁLOGOS MAESTROS POR ORGANIZACIÓN
-- =============================================================================

-- 0.1 Estados de Organizaciones (Plataforma Global)
CREATE TABLE SMY_ESTADOS_ORGANIZACIONES (
    ID                              NUMBER(10)      NOT NULL,
    NOMBRE_ESTADO                   VARCHAR2(50)    NOT NULL, -- 'ACTIVA', 'SUSPENDIDA', 'EN_PRUEBA', 'CANCELADA'
    DESCRIPCION                     VARCHAR2(200),
    FECHA_CREACION                  DATE            DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_ESTADOS_ORG PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_EST_ORG_NOM UNIQUE (NOMBRE_ESTADO)
);
CREATE SEQUENCE SEQ_SMY_ESTADOS_ORGANIZACIONES START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_ESTADOS_ORG_BI
BEFORE INSERT ON SMY_ESTADOS_ORGANIZACIONES FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_ESTADOS_ORGANIZACIONES.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
COMMENT ON TABLE SMY_ESTADOS_ORGANIZACIONES IS 'Catálogo maestro de estados operativos y contractuales para organizaciones geriátricas.';
COMMENT ON COLUMN SMY_ESTADOS_ORGANIZACIONES.ID IS 'Identificador único y clave primaria de la tabla SMY_ESTADOS_ORGANIZACIONES.';
COMMENT ON COLUMN SMY_ESTADOS_ORGANIZACIONES.NOMBRE_ESTADO IS 'Nombre descriptivo único del estado de la organización.';
COMMENT ON COLUMN SMY_ESTADOS_ORGANIZACIONES.DESCRIPCION IS 'Descripción del significado operativo del estado.';
COMMENT ON COLUMN SMY_ESTADOS_ORGANIZACIONES.FECHA_CREACION IS 'Fecha y hora de registro con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_ESTADOS_ORGANIZACIONES.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación.';

-- 0.2 Organizaciones / Entidad Raíz Multi-Tenancy
CREATE TABLE SMY_ORGANIZACIONES (
    ID                              NUMBER(10)          NOT NULL,
    CODIGO_ORGANIZACION             VARCHAR2(30)        NOT NULL, -- 'ORG-BIENESTAR', 'ORG-SANJOSE'
    RAZON_SOCIAL                    VARCHAR2(150)       NOT NULL,
    NOMBRE_COMERCIAL                VARCHAR2(120)       NOT NULL,
    NUMERO_IDENTIFICACION_TRIB      VARCHAR2(30)        NOT NULL, -- NIT / RUT
    ID_TIPO_IDENTIFICACION         NUMBER(10)          NOT NULL,
    EMAIL_CORPORATIVO               VARCHAR2(120)       NOT NULL,
    TELEFONO_CONTACTO               VARCHAR2(30),
    SITIO_WEB                       VARCHAR2(200),
    LOGO_URL                        VARCHAR2(500),
    ID_ESTADO_ORGANIZACION          NUMBER(10)          DEFAULT 1 NOT NULL,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_ORGANIZACIONES PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_ORG_COD UNIQUE (CODIGO_ORGANIZACION),
    CONSTRAINT UQ_SMY_ORG_NIT UNIQUE (NUMERO_IDENTIFICACION_TRIB),
    CONSTRAINT FK_SMY_ORG_ESTADO FOREIGN KEY (ID_ESTADO_ORGANIZACION) REFERENCES SMY_ESTADOS_ORGANIZACIONES (ID)
);
CREATE SEQUENCE SEQ_SMY_ORGANIZACIONES START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_ORGANIZACIONES_BI
BEFORE INSERT ON SMY_ORGANIZACIONES FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_ORGANIZACIONES.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
COMMENT ON TABLE SMY_ORGANIZACIONES IS 'Entidad raíz de negocio para arquitectura multi-tenancy: agrupa múltiples sedes y centros geriátricos bajo una misma personería jurídica o franquicia.';
COMMENT ON COLUMN SMY_ORGANIZACIONES.ID IS 'Identificador único y clave primaria de la tabla SMY_ORGANIZACIONES.';
COMMENT ON COLUMN SMY_ORGANIZACIONES.CODIGO_ORGANIZACION IS 'Código de negocio único de la organización o tenant (ej. ORG-BIENESTAR).';
COMMENT ON COLUMN SMY_ORGANIZACIONES.RAZON_SOCIAL IS 'Razón social legalmente registrada ante entidades tributarias.';
COMMENT ON COLUMN SMY_ORGANIZACIONES.NOMBRE_COMERCIAL IS 'Nombre de marca comercial de la institución geriátrica.';
COMMENT ON COLUMN SMY_ORGANIZACIONES.NUMERO_IDENTIFICACION_TRIB IS 'Número de identificación tributaria (NIT, CIF o RUT).';
COMMENT ON COLUMN SMY_ORGANIZACIONES.ID_TIPO_IDENTIFICACION IS 'Clave foránea hacia SMY_TIPOS_IDENTIFICACION(ID) del documento fiscal.';
COMMENT ON COLUMN SMY_ORGANIZACIONES.EMAIL_CORPORATIVO IS 'Correo electrónico corporativo principal de contacto.';
COMMENT ON COLUMN SMY_ORGANIZACIONES.TELEFONO_CONTACTO IS 'Número telefónico corporativo de la organización.';
COMMENT ON COLUMN SMY_ORGANIZACIONES.SITIO_WEB IS 'Dirección web o portal institucional.';
COMMENT ON COLUMN SMY_ORGANIZACIONES.LOGO_URL IS 'URL del logotipo oficial de la organización.';
COMMENT ON COLUMN SMY_ORGANIZACIONES.ID_ESTADO_ORGANIZACION IS 'Clave foránea hacia SMY_ESTADOS_ORGANIZACIONES(ID).';
COMMENT ON COLUMN SMY_ORGANIZACIONES.FECHA_CREACION IS 'Fecha y hora de registro con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_ORGANIZACIONES.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación.';

-- 0.1 Estados de Roles
CREATE TABLE SMY_ESTADOS_ROLES (
    ID                              NUMBER(10)      NOT NULL,
    ID_ORGANIZACION                 NUMBER(10)      NOT NULL,
    NOMBRE_ESTADO_ROL               VARCHAR2(50)    NOT NULL,
    FECHA_CREACION                  DATE            DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_ESTADOS_ROLES PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_EST_ROL_NOM UNIQUE (ID_ORGANIZACION, NOMBRE_ESTADO_ROL),
    CONSTRAINT FK_EST_ROL_ORG FOREIGN KEY (ID_ORGANIZACION) REFERENCES SMY_ORGANIZACIONES (ID)
);
CREATE SEQUENCE SEQ_SMY_ESTADOS_ROLES START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_ESTADOS_ROLES_BI
BEFORE INSERT ON SMY_ESTADOS_ROLES FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_ESTADOS_ROLES.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_ESTADOS_ROLES
COMMENT ON TABLE SMY_ESTADOS_ROLES IS 'Catálogo maestro de estados para roles del sistema (ej. Activo, Inactivo).';
COMMENT ON COLUMN SMY_ESTADOS_ROLES.ID_ORGANIZACION IS 'Clave foránea obligatoria hacia SMY_ORGANIZACIONES(ID). Multi-tenancy.';
COMMENT ON COLUMN SMY_ESTADOS_ROLES.ID IS 'Identificador único y clave primaria de la tabla SMY_ESTADOS_ROLES.';
COMMENT ON COLUMN SMY_ESTADOS_ROLES.NOMBRE_ESTADO_ROL IS 'Nombre descriptivo único correspondiente a: estado rol.';
COMMENT ON COLUMN SMY_ESTADOS_ROLES.FECHA_CREACION IS 'Fecha y hora de registro en base de datos con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_ESTADOS_ROLES.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación del registro.';

