    NOMBRE                          VARCHAR2(80)        NOT NULL,
    DESCRIPCION                     VARCHAR2(255),
    ID_ESTADO_ROL                   NUMBER(10)          NOT NULL,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_ROLES PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_ROLES_CODIGO UNIQUE (ID_ORGANIZACION, CODIGO),
    CONSTRAINT FK_SMY_ROLES_ESTADO FOREIGN KEY (ID_ESTADO_ROL) REFERENCES SMY_ESTADOS_ROLES (ID),
    CONSTRAINT FK_ROLES_ORG FOREIGN KEY (ID_ORGANIZACION) REFERENCES SMY_ORGANIZACIONES (ID)
);
CREATE SEQUENCE SEQ_SMY_ROLES START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_ROLES_BI
BEFORE INSERT ON SMY_ROLES FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_ROLES.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_ROLES
COMMENT ON TABLE SMY_ROLES IS 'Catálogo de perfiles y roles que gobiernan las vistas, permisos y privilegios del sistema.';
COMMENT ON COLUMN SMY_ROLES.ID_ORGANIZACION IS 'Clave foránea obligatoria hacia SMY_ORGANIZACIONES(ID). Multi-tenancy.';
COMMENT ON COLUMN SMY_ROLES.ID IS 'Identificador único y clave primaria de la tabla SMY_ROLES.';
COMMENT ON COLUMN SMY_ROLES.CODIGO IS 'Código mnemotécnico único del rol (ej. ADMIN, CUIDADOR, FAMILIAR).';
COMMENT ON COLUMN SMY_ROLES.NOMBRE IS 'Nombre descriptivo del perfil de acceso.';
COMMENT ON COLUMN SMY_ROLES.DESCRIPCION IS 'Descripción detallada del alcance y responsabilidades del rol.';
COMMENT ON COLUMN SMY_ROLES.ID_ESTADO_ROL IS 'Clave foránea hacia SMY_ESTADOS_ROLES(ID).';
COMMENT ON COLUMN SMY_ROLES.FECHA_CREACION IS 'Fecha y hora de registro en base de datos con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_ROLES.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación del registro.';

-- Tabla: SMY_USUARIOS
CREATE TABLE SMY_USUARIOS (
    ID                              NUMBER(10)          NOT NULL,
    ID_ROL                          NUMBER(10)          NOT NULL,
    ID_TIPO_USUARIO                 NUMBER(10)          NOT NULL,
    USERNAME                        VARCHAR2(60)        NOT NULL,
    EMAIL                           VARCHAR2(120)       NOT NULL,
    PASSWORD_HASH                   VARCHAR2(255)       NOT NULL,
    NOMBRE_COMPLETO                 VARCHAR2(150)       NOT NULL,
    TELEFONO                        VARCHAR2(30),
    AVATAR_URL                      VARCHAR2(500),
    ID_CANAL_NOTIF_PREF             NUMBER(10)          NOT NULL,
    ID_ESTADO_USUARIO               NUMBER(10)          NOT NULL,
    ULTIMO_ACCESO                   DATE,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_USUARIOS PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_USUARIOS_USER UNIQUE (USERNAME),
    CONSTRAINT UQ_SMY_USUARIOS_EMAIL UNIQUE (EMAIL),
    CONSTRAINT FK_SMY_USUARIOS_ROL FOREIGN KEY (ID_ROL) REFERENCES SMY_ROLES (ID),
    CONSTRAINT FK_SMY_USUARIOS_TIPO FOREIGN KEY (ID_TIPO_USUARIO) REFERENCES SMY_TIPOS_USUARIOS (ID),
    CONSTRAINT FK_SMY_USUARIOS_CANAL FOREIGN KEY (ID_CANAL_NOTIF_PREF) REFERENCES SMY_CANALES_NOTIFICACION (ID),
    CONSTRAINT FK_SMY_USUARIOS_ESTADO FOREIGN KEY (ID_ESTADO_USUARIO) REFERENCES SMY_ESTADOS_USUARIOS (ID)
);
CREATE SEQUENCE SEQ_SMY_USUARIOS START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_USUARIOS_BI
BEFORE INSERT ON SMY_USUARIOS FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_USUARIOS.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_USUARIOS
COMMENT ON TABLE SMY_USUARIOS IS 'Cuentas de usuario con credenciales seguras, hash criptográfico y preferencias de contacto.';
COMMENT ON COLUMN SMY_USUARIOS.ID IS 'Identificador único y clave primaria de la tabla SMY_USUARIOS.';
COMMENT ON COLUMN SMY_USUARIOS.ID_ROL IS 'Clave foránea hacia SMY_ROLES(ID) que determina los privilegios de la cuenta.';
COMMENT ON COLUMN SMY_USUARIOS.ID_TIPO_USUARIO IS 'Clave foránea hacia SMY_TIPOS_USUARIOS(ID) (ADMIN, EMPLEADO, ACUDIENTE).';
COMMENT ON COLUMN SMY_USUARIOS.USERNAME IS 'Nombre de usuario único para autenticación en la plataforma.';
COMMENT ON COLUMN SMY_USUARIOS.EMAIL IS 'Correo electrónico institucional o de contacto del usuario.';
COMMENT ON COLUMN SMY_USUARIOS.PASSWORD_HASH IS 'Hash criptográfico de la contraseña de acceso (bcrypt/PBKDF2/SHA-256).';
COMMENT ON COLUMN SMY_USUARIOS.NOMBRE_COMPLETO IS 'Nombre descriptivo único correspondiente a: completo.';
COMMENT ON COLUMN SMY_USUARIOS.TELEFONO IS 'Campo de datos para telefono en SMY_USUARIOS.';
COMMENT ON COLUMN SMY_USUARIOS.AVATAR_URL IS 'Campo de datos para avatar url en SMY_USUARIOS.';
COMMENT ON COLUMN SMY_USUARIOS.ID_CANAL_NOTIF_PREF IS 'Clave foránea hacia SMY_CANALES_NOTIFICACION(ID) con el canal preferido.';
COMMENT ON COLUMN SMY_USUARIOS.ID_ESTADO_USUARIO IS 'Clave foránea hacia SMY_ESTADOS_USUARIOS(ID) (ACTIVO, INACTIVO, BLOQUEADO).';
COMMENT ON COLUMN SMY_USUARIOS.ULTIMO_ACCESO IS 'Fecha y hora del último inicio de sesión exitoso.';
COMMENT ON COLUMN SMY_USUARIOS.FECHA_CREACION IS 'Fecha y hora de registro en base de datos con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_USUARIOS.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación del registro.';

-- Tabla: SMY_AUDITORIA_ACCESOS
CREATE TABLE SMY_AUDITORIA_ACCESOS (
    ID                              NUMBER(10)          NOT NULL,
    ID_USUARIO                      NUMBER(10)          NOT NULL,
    ACCION                          VARCHAR2(80)        NOT NULL,
    TABLA_AFECTADA                  VARCHAR2(60),
    REGISTRO_ID                     NUMBER(10),
    DIRECCION_IP                    VARCHAR2(45),
    DETALLES                        CLOB,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_AUDITORIA_ACCESOS PRIMARY KEY (ID),
    CONSTRAINT FK_SMY_AUDIT_USUARIO FOREIGN KEY (ID_USUARIO) REFERENCES SMY_USUARIOS (ID)
);
CREATE SEQUENCE SEQ_SMY_AUDITORIA_ACCESOS START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_AUDITORIA_ACC_BI
BEFORE INSERT ON SMY_AUDITORIA_ACCESOS FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_AUDITORIA_ACCESOS.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_AUDITORIA_ACCESOS
COMMENT ON TABLE SMY_AUDITORIA_ACCESOS IS 'Registro inmutable de trazabilidad para inicios de sesión, cierres y acciones críticas del sistema.';
COMMENT ON COLUMN SMY_AUDITORIA_ACCESOS.ID IS 'Identificador único y clave primaria de la tabla SMY_AUDITORIA_ACCESOS.';
COMMENT ON COLUMN SMY_AUDITORIA_ACCESOS.ID_USUARIO IS 'Clave foránea hacia SMY_USUARIOS(ID) correspondiente a la cuenta.';
COMMENT ON COLUMN SMY_AUDITORIA_ACCESOS.ACCION IS 'Acción de seguridad ejecutada (ej. LOGIN_EXITOSO, LOGIN_FALLIDO, LOGOUT, EXPORT).';
COMMENT ON COLUMN SMY_AUDITORIA_ACCESOS.TABLA_AFECTADA IS 'Nombre de la tabla afectada si la acción involucró manipulación de datos.';
COMMENT ON COLUMN SMY_AUDITORIA_ACCESOS.REGISTRO_ID IS 'Identificador del registro principal consultado o modificado.';
COMMENT ON COLUMN SMY_AUDITORIA_ACCESOS.DIRECCION_IP IS 'Dirección IP de origen desde donde se realizó la solicitud.';
COMMENT ON COLUMN SMY_AUDITORIA_ACCESOS.DETALLES IS 'Detalle contextual complementario en formato JSON o texto plano.';
COMMENT ON COLUMN SMY_AUDITORIA_ACCESOS.FECHA_CREACION IS 'Fecha y hora de registro en base de datos con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_AUDITORIA_ACCESOS.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación del registro.';

-- 1.4 Tabla: SMY_ERRORES (Control y Registro de Errores)
CREATE TABLE SMY_ERRORES
(
    ID                     NUMBER NOT NULL,
    TIPO                   VARCHAR2 (1 BYTE) DEFAULT 'E' NOT NULL,
    NOMBRE_PROGRAMA        VARCHAR2 (50 BYTE) NOT NULL,
    NOMBRE_METODO          VARCHAR2 (50 BYTE),
    PARAMETROS             CLOB,
    DIRECCION_IP           VARCHAR2(30),
    USUARIO                VARCHAR2 (200 BYTE),
    CODIGO_ERROR           VARCHAR2 (100 BYTE),
    TEXTO_ERROR            VARCHAR2 (4000 BYTE),
    MENSAJE_ERROR          VARCHAR2 (4000 BYTE),
    FECHA_CREACION         DATE DEFAULT CAST(systimestamp AT TIME ZONE '-05:00' AS DATE),
    ID_USUARIO_CREACION    NUMBER,
    CONSTRAINT PK_SMY_ERRORES PRIMARY KEY (ID)
);
CREATE SEQUENCE SEQ_SMY_ERRORES START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_ERRORES_BI
BEFORE INSERT ON SMY_ERRORES FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_ERRORES.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_ERRORES
COMMENT ON TABLE SMY_ERRORES IS 'Bitácora centralizada para captura, diagnóstico y auditoría forense de excepciones y errores del sistema.';
COMMENT ON COLUMN SMY_ERRORES.ID IS 'Identificador único y clave primaria de la tabla SMY_ERRORES.';
COMMENT ON COLUMN SMY_ERRORES.TIPO IS 'Tipo o severidad del registro (''E''=Error, ''W''=Advertencia, ''I''=Información).';
COMMENT ON COLUMN SMY_ERRORES.NOMBRE_PROGRAMA IS 'Nombre descriptivo único correspondiente a: programa.';
COMMENT ON COLUMN SMY_ERRORES.NOMBRE_METODO IS 'Nombre descriptivo único correspondiente a: metodo.';
COMMENT ON COLUMN SMY_ERRORES.PARAMETROS IS 'Parámetros de entrada o payload serializado (JSON/texto) presente en la solicitud fallida.';
COMMENT ON COLUMN SMY_ERRORES.DIRECCION_IP IS 'Dirección IP del cliente, dispositivo o servidor solicitante.';
COMMENT ON COLUMN SMY_ERRORES.USUARIO IS 'Nombre de usuario o login de la cuenta activa al momento de la falla.';
COMMENT ON COLUMN SMY_ERRORES.CODIGO_ERROR IS 'Código técnico de error retornado por la base de datos (ej. ORA-XXXXX) o aplicación.';
COMMENT ON COLUMN SMY_ERRORES.TEXTO_ERROR IS 'Traza técnica detallada del error, stack trace o mensaje técnico del motor/servidor.';
COMMENT ON COLUMN SMY_ERRORES.MENSAJE_ERROR IS 'Mensaje de error procesado y comprensible para el usuario o soporte funcional.';
COMMENT ON COLUMN SMY_ERRORES.FECHA_CREACION IS 'Fecha y hora de registro en base de datos con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_ERRORES.ID_USUARIO_CREACION IS 'Identificador del usuario que originó o registró el evento.';

-- Tabla: SMY_ORGANIZACION_DUENOS
CREATE TABLE SMY_ORGANIZACION_DUENOS (
    ID                              NUMBER(10)          NOT NULL,
    ID_ORGANIZACION                 NUMBER(10)          NOT NULL,
    ID_USUARIO                      NUMBER(10)          NOT NULL,
    PORCENTAJE_PARTICIPACION        NUMBER(5,2)         DEFAULT 100.00,
    ES_REPRESENTANTE_LEGAL          CHAR(1)             DEFAULT 'S' NOT NULL,
    FECHA_VINCULACION               DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    FECHA_RETIRO                    DATE,
    ESTADO_ACTIVO                   CHAR(1)             DEFAULT 'S' NOT NULL,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_ORG_DUENOS PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_ORG_DUE UNIQUE (ID_ORGANIZACION, ID_USUARIO),
    CONSTRAINT CK_SMY_ORG_DUE_REP CHECK (ES_REPRESENTANTE_LEGAL IN ('S', 'N')),
    CONSTRAINT CK_SMY_ORG_DUE_ACT CHECK (ESTADO_ACTIVO IN ('S', 'N')),
    CONSTRAINT FK_SMY_ORG_DUE_ORG FOREIGN KEY (ID_ORGANIZACION) REFERENCES SMY_ORGANIZACIONES (ID),
    CONSTRAINT FK_SMY_ORG_DUE_USR FOREIGN KEY (ID_USUARIO) REFERENCES SMY_USUARIOS (ID)
);
CREATE SEQUENCE SEQ_SMY_ORGANIZACION_DUENOS START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_ORG_DUENOS_BI
BEFORE INSERT ON SMY_ORGANIZACION_DUENOS FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_ORGANIZACION_DUENOS.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
COMMENT ON TABLE SMY_ORGANIZACION_DUENOS IS 'Registro de personas propietarias/socias con titularidad sobre organizaciones y franquicias geriátricas.';
COMMENT ON COLUMN SMY_ORGANIZACION_DUENOS.ID IS 'Identificador único y clave primaria de la tabla SMY_ORGANIZACION_DUENOS.';
COMMENT ON COLUMN SMY_ORGANIZACION_DUENOS.ID_ORGANIZACION IS 'Clave foránea hacia SMY_ORGANIZACIONES(ID).';
COMMENT ON COLUMN SMY_ORGANIZACION_DUENOS.ID_USUARIO IS 'Clave foránea hacia SMY_USUARIOS(ID) del propietario.';
COMMENT ON COLUMN SMY_ORGANIZACION_DUENOS.PORCENTAJE_PARTICIPACION IS 'Porcentaje de participación patrimonial o societaria en la organización.';
COMMENT ON COLUMN SMY_ORGANIZACION_DUENOS.ES_REPRESENTANTE_LEGAL IS 'Indicador booleano (S/N) si el usuario es representante legal.';
COMMENT ON COLUMN SMY_ORGANIZACION_DUENOS.FECHA_VINCULACION IS 'Fecha en que adquiere la condición de dueño o socio.';
COMMENT ON COLUMN SMY_ORGANIZACION_DUENOS.FECHA_RETIRO IS 'Fecha de cesión o retiro de la participación societaria.';
COMMENT ON COLUMN SMY_ORGANIZACION_DUENOS.ESTADO_ACTIVO IS 'Indicador booleano (S/N) de vinculación activa.';
COMMENT ON COLUMN SMY_ORGANIZACION_DUENOS.FECHA_CREACION IS 'Fecha y hora de registro con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_ORGANIZACION_DUENOS.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación.';

-- Tabla: SMY_CENTRO_USUARIOS
CREATE TABLE SMY_CENTRO_USUARIOS (
    ID                              NUMBER(10)          NOT NULL,
    ID_CENTRO                       NUMBER(10)          NOT NULL,
    ID_USUARIO                      NUMBER(10)          NOT NULL,
    ID_ROL                          NUMBER(10)          NOT NULL,
    ES_SEDE_PRINCIPAL               CHAR(1)             DEFAULT 'N' NOT NULL,
    ESTADO_ACTIVO                   CHAR(1)             DEFAULT 'S' NOT NULL,
    FECHA_ASIGNACION                DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_CENTRO_USUARIOS PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_CEN_USR UNIQUE (ID_CENTRO, ID_USUARIO, ID_ROL),
    CONSTRAINT CK_SMY_CEN_USR_PRI CHECK (ES_SEDE_PRINCIPAL IN ('S', 'N')),
    CONSTRAINT CK_SMY_CEN_USR_ACT CHECK (ESTADO_ACTIVO IN ('S', 'N')),
    CONSTRAINT FK_SMY_CEN_USR_CEN FOREIGN KEY (ID_CENTRO) REFERENCES SMY_CENTROS (ID),
    CONSTRAINT FK_SMY_CEN_USR_USR FOREIGN KEY (ID_USUARIO) REFERENCES SMY_USUARIOS (ID),
    CONSTRAINT FK_SMY_CEN_USR_ROL FOREIGN KEY (ID_ROL) REFERENCES SMY_ROLES (ID)
);
CREATE SEQUENCE SEQ_SMY_CENTRO_USUARIOS START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_CENTRO_USUARIOS_BI
BEFORE INSERT ON SMY_CENTRO_USUARIOS FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_CENTRO_USUARIOS.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
COMMENT ON TABLE SMY_CENTRO_USUARIOS IS 'Asignación de usuarios a centros/sedes geriátricas con rol específico por sede. Permite a una persona administrar o laborar en múltiples centros.';
COMMENT ON COLUMN SMY_CENTRO_USUARIOS.ID IS 'Identificador único y clave primaria de la tabla SMY_CENTRO_USUARIOS.';
COMMENT ON COLUMN SMY_CENTRO_USUARIOS.ID_CENTRO IS 'Clave foránea hacia SMY_CENTROS(ID) donde opera el usuario.';
COMMENT ON COLUMN SMY_CENTRO_USUARIOS.ID_USUARIO IS 'Clave foránea hacia SMY_USUARIOS(ID).';
COMMENT ON COLUMN SMY_CENTRO_USUARIOS.ID_ROL IS 'Clave foránea hacia SMY_ROLES(ID) que ejerce en dicho centro (ej. ADMIN, CUIDADOR, MEDICO).';
COMMENT ON COLUMN SMY_CENTRO_USUARIOS.ES_SEDE_PRINCIPAL IS 'Indicador booleano (S/N) de sede principal o preferente al iniciar sesión.';
COMMENT ON COLUMN SMY_CENTRO_USUARIOS.ESTADO_ACTIVO IS 'Indicador booleano (S/N) de vigencia de la asignación.';
COMMENT ON COLUMN SMY_CENTRO_USUARIOS.FECHA_ASIGNACION IS 'Fecha y hora en que se asigna la persona a la sede.';
COMMENT ON COLUMN SMY_CENTRO_USUARIOS.FECHA_CREACION IS 'Fecha y hora de registro con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_CENTRO_USUARIOS.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación.';

-- Tabla: SMY_PARAMETROS
CREATE TABLE SMY_PARAMETROS (
    ID                              NUMBER(10)          NOT NULL,
    ID_ORGANIZACION                 NUMBER(10),                             -- Parámetro a nivel de negocio/tenant
    ID_CENTRO                       NUMBER(10),                             -- Parámetro a nivel de sede física
    CODIGO_PARAMETRO                VARCHAR2(100)       NOT NULL, -- 'API_TOKEN_WHATSAPP', 'STORAGE_BASE_PATH', 'ORACLE_WALLET_PATH'
    NOMBRE_PARAMETRO                VARCHAR2(150)       NOT NULL,
    DESCRIPCION                     VARCHAR2(500),
    GRUPO_PARAMETRO                 VARCHAR2(50)        DEFAULT 'GENERAL' NOT NULL, -- 'INTEGRACION', 'STORAGE', 'SEGURIDAD', 'NOTIFICACIONES'
    VALOR_TEXTO                     VARCHAR2(4000),     -- Valores de texto estándar, URLs, rutas
    VALOR_CLOB                      CLOB,               -- Tokens JWT extensos, certificados PEM, configuraciones JSON complejas
    VALOR_NUMERICO                  NUMBER(18, 4),      -- Límites, timeouts en segundos, cuotas
    VALOR_FECHA                     DATE,               -- Vencimiento de tokens, fecha de rotación de credenciales
    ES_ENCRIPTADO                   CHAR(1)             DEFAULT 'N' NOT NULL, -- 'S'=Encriptado con AES/Wallet, 'N'=Plano
    ES_SISTEMA                      CHAR(1)             DEFAULT 'N' NOT NULL, -- 'S'=Protegido contra eliminación accidental, 'N'=Editable
    ID_ESTADO_PARAMETRO             NUMBER(10)          DEFAULT 1 NOT NULL,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    FECHA_ULTIMA_MODIFICACION       DATE,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_PARAMETROS PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_PAR_CODIGO UNIQUE (CODIGO_PARAMETRO),
    CONSTRAINT CK_SMY_PAR_ENCRIPTADO CHECK (ES_ENCRIPTADO IN ('S', 'N')),
    CONSTRAINT CK_SMY_PAR_SISTEMA CHECK (ES_SISTEMA IN ('S', 'N')),
    CONSTRAINT FK_SMY_PAR_ORG FOREIGN KEY (ID_ORGANIZACION) REFERENCES SMY_ORGANIZACIONES (ID),
    CONSTRAINT FK_SMY_PAR_CEN FOREIGN KEY (ID_CENTRO) REFERENCES SMY_CENTROS (ID),
    CONSTRAINT FK_SMY_PAR_ESTADO FOREIGN KEY (ID_ESTADO_PARAMETRO) REFERENCES SMY_ESTADOS_PARAMETROS (ID)
);
CREATE SEQUENCE SEQ_SMY_PARAMETROS START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_PARAMETROS_BI
BEFORE INSERT ON SMY_PARAMETROS FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_PARAMETROS.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
    :NEW.FECHA_ULTIMA_MODIFICACION := CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE);
END;
/
CREATE OR REPLACE TRIGGER TRG_SMY_PARAMETROS_BU
BEFORE UPDATE ON SMY_PARAMETROS FOR EACH ROW
BEGIN
    :NEW.FECHA_ULTIMA_MODIFICACION := CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE);
END;
/
COMMENT ON TABLE SMY_PARAMETROS IS 'Tabla central de parámetros de configuración del sistema: tokens de APIs, credenciales de conexión, URLs y flags de comportamiento a nivel global, de organización o centro.';
COMMENT ON COLUMN SMY_PARAMETROS.ID IS 'Identificador único y clave primaria de la tabla SMY_PARAMETROS.';
COMMENT ON COLUMN SMY_PARAMETROS.ID_ORGANIZACION IS 'Clave foránea opcional hacia SMY_ORGANIZACIONES(ID) si el parámetro pertenece a un negocio particular.';
COMMENT ON COLUMN SMY_PARAMETROS.ID_CENTRO IS 'Clave foránea opcional hacia SMY_CENTROS(ID) si el parámetro pertenece a una sede particular.';
COMMENT ON COLUMN SMY_PARAMETROS.CODIGO_PARAMETRO IS 'Clave alfanumérica única del parámetro (ej. STORAGE_LOCAL_ROOT, API_TOKEN_WHATSAPP).';
COMMENT ON COLUMN SMY_PARAMETROS.NOMBRE_PARAMETRO IS 'Nombre comprensible para administración técnica.';
COMMENT ON COLUMN SMY_PARAMETROS.DESCRIPCION IS 'Documentación funcional sobre el propósito y uso del parámetro.';
COMMENT ON COLUMN SMY_PARAMETROS.GRUPO_PARAMETRO IS 'Agrupador temático del parámetro (INTEGRACION, STORAGE, SEGURIDAD, NOTIFICACIONES).';
COMMENT ON COLUMN SMY_PARAMETROS.VALOR_TEXTO IS 'Valor de configuración en formato cadena de texto hasta 4000 caracteres.';
COMMENT ON COLUMN SMY_PARAMETROS.VALOR_CLOB IS 'Almacén de longitud extendida para tokens JWT largos, llaves privadas, certificados o JSON.';
COMMENT ON COLUMN SMY_PARAMETROS.VALOR_NUMERICO IS 'Valor numérico para tiempos de espera, puertos o tamaños máximos.';
COMMENT ON COLUMN SMY_PARAMETROS.VALOR_FECHA IS 'Fecha límite de vigencia de tokens o rotación de contraseñas.';
COMMENT ON COLUMN SMY_PARAMETROS.ES_ENCRIPTADO IS 'Indicador booleano (S/N) que especifica si el contenido debe tratarse cifrado.';
COMMENT ON COLUMN SMY_PARAMETROS.ES_SISTEMA IS 'Indicador booleano (S/N) para proteger parámetros críticos del núcleo.';
COMMENT ON COLUMN SMY_PARAMETROS.ID_ESTADO_PARAMETRO IS 'Clave foránea hacia SMY_ESTADOS_PARAMETROS (Activo/Inactivo).';
COMMENT ON COLUMN SMY_PARAMETROS.FECHA_CREACION IS 'Fecha y hora de registro con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_PARAMETROS.FECHA_ULTIMA_MODIFICACION IS 'Fecha y hora de la última modificación en base de datos.';
COMMENT ON COLUMN SMY_PARAMETROS.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación.';

-- =============================================================================
-- SECCIÓN 2: MÓDULO DE TALENTO HUMANO, TURNOS Y AUSENCIAS
-- =============================================================================

-- Tabla: SMY_EMPLEADOS
CREATE TABLE SMY_EMPLEADOS (
    ID                              NUMBER(10)          NOT NULL,
    ID_CENTRO                       NUMBER(10),                             -- Sede o centro geriátrico al que pertenece
    ID_USUARIO                      NUMBER(10),
    ID_TIPO_IDENTIFICACION         NUMBER(10)          NOT NULL,
    IDENTIFICACION                  VARCHAR2(30)        NOT NULL,
    NOMBRES                         VARCHAR2(80)        NOT NULL,
    APELLIDOS                       VARCHAR2(80)        NOT NULL,
    ID_CARGO_EMPLEADO               NUMBER(10)          NOT NULL,
    ID_AREA_EMPLEADO                NUMBER(10)          NOT NULL,
    UNIDAD_ASIGNADA                 VARCHAR2(50),
    TELEFONO                        VARCHAR2(30),
    EMAIL_CORP                      VARCHAR2(120),
    FECHA_CONTRATACION              DATE                NOT NULL,
    FECHA_TERMINACION               DATE,
    ID_ESTADO_EMPLEADO              NUMBER(10)          NOT NULL,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_EMPLEADOS PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_EMP_IDENT UNIQUE (ID_TIPO_IDENTIFICACION, IDENTIFICACION),
    CONSTRAINT FK_SMY_EMP_CENTRO FOREIGN KEY (ID_CENTRO) REFERENCES SMY_CENTROS (ID),
    CONSTRAINT FK_SMY_EMP_USUARIO FOREIGN KEY (ID_USUARIO) REFERENCES SMY_USUARIOS (ID),
    CONSTRAINT FK_SMY_EMP_TIPO_IDENT FOREIGN KEY (ID_TIPO_IDENTIFICACION) REFERENCES SMY_TIPOS_IDENTIFICACION (ID),
    CONSTRAINT FK_SMY_EMP_CARGO FOREIGN KEY (ID_CARGO_EMPLEADO) REFERENCES SMY_CARGOS_EMPLEADOS (ID),
    CONSTRAINT FK_SMY_EMP_AREA FOREIGN KEY (ID_AREA_EMPLEADO) REFERENCES SMY_AREAS_EMPLEADOS (ID),
    CONSTRAINT FK_SMY_EMP_ESTADO FOREIGN KEY (ID_ESTADO_EMPLEADO) REFERENCES SMY_ESTADOS_EMPLEADOS (ID)
);
CREATE SEQUENCE SEQ_SMY_EMPLEADOS START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_EMPLEADOS_BI
BEFORE INSERT ON SMY_EMPLEADOS FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_EMPLEADOS.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_EMPLEADOS
COMMENT ON TABLE SMY_EMPLEADOS IS 'Ficha del colaborador asistencial, médico, administrativo y de servicios de la institución.';
COMMENT ON COLUMN SMY_EMPLEADOS.ID IS 'Identificador único y clave primaria de la tabla SMY_EMPLEADOS.';
COMMENT ON COLUMN SMY_EMPLEADOS.ID_CENTRO IS 'Clave foránea hacia SMY_CENTROS(ID) con el centro geriátrico al que está adscrito el empleado.';
COMMENT ON COLUMN SMY_EMPLEADOS.ID_USUARIO IS 'Clave foránea opcional hacia SMY_USUARIOS(ID) si el empleado tiene usuario en sistema.';
COMMENT ON COLUMN SMY_EMPLEADOS.ID_TIPO_IDENTIFICACION IS 'Clave foránea hacia SMY_TIPOS_IDENTIFICACION(ID) para el tipo de documento.';
COMMENT ON COLUMN SMY_EMPLEADOS.IDENTIFICACION IS 'Número de documento o identificación oficial del empleado.';
COMMENT ON COLUMN SMY_EMPLEADOS.NOMBRES IS 'Nombres del empleado.';
COMMENT ON COLUMN SMY_EMPLEADOS.APELLIDOS IS 'Apellidos del empleado.';
COMMENT ON COLUMN SMY_EMPLEADOS.ID_CARGO_EMPLEADO IS 'Clave foránea hacia SMY_CARGOS_EMPLEADOS(ID) con el cargo laboral.';
COMMENT ON COLUMN SMY_EMPLEADOS.ID_AREA_EMPLEADO IS 'Clave foránea hacia SMY_AREAS_EMPLEADOS(ID) con el área operativa.';
COMMENT ON COLUMN SMY_EMPLEADOS.UNIDAD_ASIGNADA IS 'Sede, piso, ala o unidad asistencial asignada de base al colaborador.';
COMMENT ON COLUMN SMY_EMPLEADOS.TELEFONO IS 'Número de contacto telefónico del colaborador.';
COMMENT ON COLUMN SMY_EMPLEADOS.EMAIL_CORP IS 'Correo electrónico corporativo o personal para comunicaciones.';
COMMENT ON COLUMN SMY_EMPLEADOS.FECHA_CONTRATACION IS 'Fecha de inicio del contrato laboral.';
COMMENT ON COLUMN SMY_EMPLEADOS.FECHA_TERMINACION IS 'Fecha de terminación o cese del contrato laboral (si aplica).';
COMMENT ON COLUMN SMY_EMPLEADOS.ID_ESTADO_EMPLEADO IS 'Clave foránea hacia SMY_ESTADOS_EMPLEADOS(ID) (Activo, Inactivo, etc.).';
COMMENT ON COLUMN SMY_EMPLEADOS.FECHA_CREACION IS 'Fecha y hora de registro en base de datos con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_EMPLEADOS.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación del registro.';

-- Tabla: SMY_DOCUMENTOS_EMPLEADO
CREATE TABLE SMY_DOCUMENTOS_EMPLEADO (
    ID                              NUMBER(10)          NOT NULL,
    ID_EMPLEADO                     NUMBER(10)          NOT NULL,
    TIPO_DOCUMENTO                  VARCHAR2(60)        NOT NULL,
    NOMBRE_ARCHIVO                  VARCHAR2(255)       NOT NULL,
    URL_ARCHIVO                     VARCHAR2(500)       NOT NULL,
    FECHA_EXPEDICION                DATE,
    FECHA_VENCIMIENTO               DATE,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_DOCS_EMP PRIMARY KEY (ID),
    CONSTRAINT FK_SMY_DOC_EMP_EMP FOREIGN KEY (ID_EMPLEADO) REFERENCES SMY_EMPLEADOS (ID) ON DELETE CASCADE
);
CREATE SEQUENCE SEQ_SMY_DOCUMENTOS_EMPLEADO START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_DOCS_EMP_BI
BEFORE INSERT ON SMY_DOCUMENTOS_EMPLEADO FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_DOCUMENTOS_EMPLEADO.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_DOCUMENTOS_EMPLEADO
COMMENT ON TABLE SMY_DOCUMENTOS_EMPLEADO IS 'Repositorio digital de legajos, contratos, certificados y soportes documentales del empleado.';
COMMENT ON COLUMN SMY_DOCUMENTOS_EMPLEADO.ID IS 'Identificador único y clave primaria de la tabla SMY_DOCUMENTOS_EMPLEADO.';
COMMENT ON COLUMN SMY_DOCUMENTOS_EMPLEADO.ID_EMPLEADO IS 'Clave foránea hacia SMY_EMPLEADOS(ID) titular del documento.';
COMMENT ON COLUMN SMY_DOCUMENTOS_EMPLEADO.TIPO_DOCUMENTO IS 'Tipo de documento laboral (Hoja de Vida, Certificado, Curso, Contrato).';
COMMENT ON COLUMN SMY_DOCUMENTOS_EMPLEADO.NOMBRE_ARCHIVO IS 'Nombre descriptivo único correspondiente a: archivo.';
COMMENT ON COLUMN SMY_DOCUMENTOS_EMPLEADO.URL_ARCHIVO IS 'Ruta de almacenamiento local o URI de acceso al archivo digital.';
COMMENT ON COLUMN SMY_DOCUMENTOS_EMPLEADO.FECHA_EXPEDICION IS 'Fecha en la cual fue emitido el documento.';
COMMENT ON COLUMN SMY_DOCUMENTOS_EMPLEADO.FECHA_VENCIMIENTO IS 'Fecha de vencimiento del certificado o documento (si aplica).';
COMMENT ON COLUMN SMY_DOCUMENTOS_EMPLEADO.FECHA_CREACION IS 'Fecha y hora de registro en base de datos con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_DOCUMENTOS_EMPLEADO.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación del registro.';

-- Tabla: SMY_PLANTILLAS_TURNO
CREATE TABLE SMY_PLANTILLAS_TURNO (
    ID                              NUMBER(10)          NOT NULL,
    ID_ORGANIZACION                 NUMBER(10)      NOT NULL,
    CODIGO                          VARCHAR2(20)        NOT NULL,
    NOMBRE                          VARCHAR2(60)        NOT NULL,
    HORA_INICIO                     VARCHAR2(5)         NOT NULL, -- '06:00'
    HORA_FIN                        VARCHAR2(5)         NOT NULL, -- '14:00'
    TOTAL_HORAS                     NUMBER(4,2)         NOT NULL,
    COLOR_HEX                       VARCHAR2(10)        DEFAULT '#3B82F6',
    ID_ESTADO_PLANTILLA             NUMBER(10)          NOT NULL,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_PLANTILLAS_TURNO PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_PLANT_COD UNIQUE (ID_ORGANIZACION, CODIGO),
    CONSTRAINT FK_SMY_PLANT_ESTADO FOREIGN KEY (ID_ESTADO_PLANTILLA) REFERENCES SMY_ESTADOS_PLANTILLAS_TURNO (ID),
    CONSTRAINT FK_PLANT_ORG FOREIGN KEY (ID_ORGANIZACION) REFERENCES SMY_ORGANIZACIONES (ID)
);
CREATE SEQUENCE SEQ_SMY_PLANTILLAS_TURNO START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_PLANTILLAS_TURNO_BI
BEFORE INSERT ON SMY_PLANTILLAS_TURNO FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_PLANTILLAS_TURNO.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_PLANTILLAS_TURNO
COMMENT ON TABLE SMY_PLANTILLAS_TURNO IS 'Plantillas maestras de configuración horaria y franjas para turnos de trabajo.';
COMMENT ON COLUMN SMY_PLANTILLAS_TURNO.ID_ORGANIZACION IS 'Clave foránea obligatoria hacia SMY_ORGANIZACIONES(ID). Multi-tenancy.';
COMMENT ON COLUMN SMY_PLANTILLAS_TURNO.ID IS 'Identificador único y clave primaria de la tabla SMY_PLANTILLAS_TURNO.';
COMMENT ON COLUMN SMY_PLANTILLAS_TURNO.CODIGO IS 'Código mnemotécnico de la plantilla de turno (ej. TM, TT, TN).';
