    CONSTRAINT FK_SMY_TURNOS_PLANT FOREIGN KEY (ID_PLANTILLA_TURNO) REFERENCES SMY_PLANTILLAS_TURNO (ID),
    CONSTRAINT FK_SMY_TURNOS_ESTADO FOREIGN KEY (ID_ESTADO_TURNO) REFERENCES SMY_ESTADOS_TURNOS (ID)
);
CREATE SEQUENCE SEQ_SMY_TURNOS_ASIGNADOS START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_TURNOS_ASIG_BI
BEFORE INSERT ON SMY_TURNOS_ASIGNADOS FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_TURNOS_ASIGNADOS.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
