-- Tabla Intermedia: SMY_RESIDENTE_ACUDIENTE
CREATE TABLE SMY_RESIDENTE_ACUDIENTE (
    ID                              NUMBER(10)          NOT NULL,
    ID_RESIDENTE                    NUMBER(10)          NOT NULL,
    ID_ACUDIENTE                    NUMBER(10)          NOT NULL,
    ID_PARENTESCO                   NUMBER(10)          NOT NULL,
    ES_PRINCIPAL                    CHAR(1)             DEFAULT 'N' NOT NULL, -- 'S' / 'N'
    ES_RESPONSABLE_PAGO             CHAR(1)             DEFAULT 'N' NOT NULL, -- 'S' / 'N'
    AUTORIZADO_SALIDAS              CHAR(1)             DEFAULT 'S' NOT NULL, -- 'S' / 'N'
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_RES_ACU PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_RES_ACU UNIQUE (ID_RESIDENTE, ID_ACUDIENTE),
    CONSTRAINT FK_SMY_RA_RESIDENTE FOREIGN KEY (ID_RESIDENTE) REFERENCES SMY_RESIDENTES (ID) ON DELETE CASCADE,
    CONSTRAINT FK_SMY_RA_ACUDIENTE FOREIGN KEY (ID_ACUDIENTE) REFERENCES SMY_ACUDIENTES (ID) ON DELETE CASCADE,
    CONSTRAINT FK_SMY_RA_PARENTESCO FOREIGN KEY (ID_PARENTESCO) REFERENCES SMY_PARENTESCOS (ID),
    CONSTRAINT CK_SMY_RA_PRINCIPAL CHECK (ES_PRINCIPAL IN ('S', 'N')),
    CONSTRAINT CK_SMY_RA_PAGO CHECK (ES_RESPONSABLE_PAGO IN ('S', 'N')),
    CONSTRAINT CK_SMY_RA_SALIDAS CHECK (AUTORIZADO_SALIDAS IN ('S', 'N'))
);
CREATE SEQUENCE SEQ_SMY_RESIDENTE_ACUDIENTE START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_RES_ACU_BI
BEFORE INSERT ON SMY_RESIDENTE_ACUDIENTE FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_RESIDENTE_ACUDIENTE.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_RESIDENTE_ACUDIENTE
COMMENT ON TABLE SMY_RESIDENTE_ACUDIENTE IS 'Tabla de relación asociativa multidireccional entre residentes y sus acudientes o tutores.';
