    CONSTRAINT FK_SMY_ADM_MOVILIDAD FOREIGN KEY (ID_NIVEL_MOVILIDAD) REFERENCES SMY_NIVELES_MOVILIDAD (ID),
    CONSTRAINT FK_SMY_ADM_DIETA FOREIGN KEY (ID_TIPO_DIETA) REFERENCES SMY_TIPOS_DIETAS (ID),
    CONSTRAINT FK_SMY_ADM_ESTADO FOREIGN KEY (ID_ESTADO_SOLICITUD_ADM) REFERENCES SMY_ESTADOS_SOLICITUDES_ADM (ID),
    CONSTRAINT FK_SMY_ADM_RES_CREADO FOREIGN KEY (ID_RESIDENTE_CREADO) REFERENCES SMY_RESIDENTES (ID),
    CONSTRAINT FK_SMY_ADM_REVISOR FOREIGN KEY (ID_USUARIO_REVISO) REFERENCES SMY_USUARIOS (ID)
);
