    CONSTRAINT FK_SMY_DC_USUARIO FOREIGN KEY (ID_USUARIO) REFERENCES SMY_USUARIOS (ID),
    CONSTRAINT FK_SMY_DC_ESTADO FOREIGN KEY (ID_ESTADO_DOC_CLINICO) REFERENCES SMY_ESTADOS_DOC_CLINICOS (ID)
);
CREATE SEQUENCE SEQ_SMY_DOCUMENTOS_CLINICOS START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_DOC_CLIN_BI
BEFORE INSERT ON SMY_DOCUMENTOS_CLINICOS FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_DOCUMENTOS_CLINICOS.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
