COMMENT ON TABLE SMY_DOCUMENTOS_CLINICOS IS 'Repositorio digital de documentos clínicos, evoluciones médicas, órdenes y exámenes anexos.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.ID IS 'Identificador único y clave primaria de la tabla SMY_DOCUMENTOS_CLINICOS.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.ID_RESIDENTE IS 'Clave foránea hacia SMY_RESIDENTES(ID) asociado al documento.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.TITULO IS 'Título o encabezado descriptivo del documento clínico.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.ID_CATEGORIA_DOC_CLINICO IS 'Clave foránea hacia SMY_CATEGORIAS_DOC_CLINICOS(ID).';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.DESCRIPCION IS 'Descripción detallada de descripcion.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.ID_TIPO_ENTRADA_DOC IS 'Clave foránea hacia SMY_TIPOS_ENTRADAS_DOC(ID).';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.ID_TIPO_ARCHIVO_DOC IS 'Clave foránea hacia SMY_TIPOS_ARCHIVOS_DOC(ID).';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.NOMBRE_ARCHIVO IS 'Nombre descriptivo único correspondiente a: archivo.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.PESO_ARCHIVO IS 'Campo de datos para peso archivo en SMY_DOCUMENTOS_CLINICOS.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.URL_ARCHIVO IS 'Campo de datos para url archivo en SMY_DOCUMENTOS_CLINICOS.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.SUBIDO_POR_ROL IS 'Campo de datos para subido por rol en SMY_DOCUMENTOS_CLINICOS.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.SUBIDO_POR_NOMBRE IS 'Campo de datos para subido por nombre en SMY_DOCUMENTOS_CLINICOS.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.ID_USUARIO IS 'Clave foránea que referencia al registro correspondiente a: usuario.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.FECHA_DOCUMENTO IS 'Fecha clínica del hecho, atención o examen médico.';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.ID_ESTADO_DOC_CLINICO IS 'Clave foránea hacia SMY_ESTADOS_DOC_CLINICOS(ID).';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.FECHA_CREACION IS 'Fecha y hora de registro en base de datos con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_DOCUMENTOS_CLINICOS.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación del registro.';

-- Tabla: SMY_DOCUMENTOS_ELIMINADOS_LOG (Papelera / Auditoría)
CREATE TABLE SMY_DOCUMENTOS_ELIMINADOS_LOG (
    ID                              NUMBER(10)          NOT NULL,
    ID_DOCUMENTO_CLINICO            NUMBER(10)          NOT NULL,
    ID_RESIDENTE                    NUMBER(10)          NOT NULL,
    TITULO                          VARCHAR2(150)       NOT NULL,
    ID_CATEGORIA_DOC_CLINICO        NUMBER(10),
    NOMBRE_ARCHIVO                  VARCHAR2(255),
    URL_ARCHIVO                     VARCHAR2(500),
    SUBIDO_POR_NOMBRE               VARCHAR2(120),
    ID_USUARIO_ELIMINO              NUMBER(10),
    ELIMINADO_POR_NOM               VARCHAR2(120)       NOT NULL,
    MOTIVO_ELIMINACION              VARCHAR2(255),
    FECHA_ELIMINACION               DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_DOC_ELIM_LOG PRIMARY KEY (ID),
    CONSTRAINT FK_SMY_DEL_DOC_CAT FOREIGN KEY (ID_CATEGORIA_DOC_CLINICO) REFERENCES SMY_CATEGORIAS_DOC_CLINICOS (ID),
    CONSTRAINT FK_SMY_DEL_DOC_USER FOREIGN KEY (ID_USUARIO_ELIMINO) REFERENCES SMY_USUARIOS (ID)
);
CREATE SEQUENCE SEQ_SMY_DOC_ELIM_LOG START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_DOC_ELIM_LOG_BI
BEFORE INSERT ON SMY_DOCUMENTOS_ELIMINADOS_LOG FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_DOC_ELIM_LOG.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_DOCUMENTOS_ELIMINADOS_LOG
COMMENT ON TABLE SMY_DOCUMENTOS_ELIMINADOS_LOG IS 'Registro inmutable de auditoría forense ante la anulación o eliminación de documentos clínicos.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.ID IS 'Identificador único y clave primaria de la tabla SMY_DOCUMENTOS_ELIMINADOS_LOG.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.ID_DOCUMENTO_CLINICO IS 'Clave foránea que referencia al registro correspondiente a: documento clinico.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.ID_RESIDENTE IS 'Clave foránea hacia SMY_RESIDENTES(ID) que estaba vinculado.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.TITULO IS 'Campo de datos para titulo en SMY_DOCUMENTOS_ELIMINADOS_LOG.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.ID_CATEGORIA_DOC_CLINICO IS 'Clave foránea que referencia al registro correspondiente a: categoria doc clinico.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.NOMBRE_ARCHIVO IS 'Nombre descriptivo único correspondiente a: archivo.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.URL_ARCHIVO IS 'Campo de datos para url archivo en SMY_DOCUMENTOS_ELIMINADOS_LOG.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.SUBIDO_POR_NOMBRE IS 'Campo de datos para subido por nombre en SMY_DOCUMENTOS_ELIMINADOS_LOG.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.ID_USUARIO_ELIMINO IS 'Clave foránea hacia SMY_USUARIOS(ID) del usuario ejecutor.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.ELIMINADO_POR_NOM IS 'Campo de datos para eliminado por nom en SMY_DOCUMENTOS_ELIMINADOS_LOG.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.MOTIVO_ELIMINACION IS 'Causa o justificación médica/legal formal para anular el registro.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.FECHA_ELIMINACION IS 'Fecha y hora exacta en que se efectuó la anulación en sistema.';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.FECHA_CREACION IS 'Fecha y hora de registro en base de datos con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_DOCUMENTOS_ELIMINADOS_LOG.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación del registro.';

-- Tabla: SMY_ARCHIVOS
CREATE TABLE SMY_ARCHIVOS (
    ID                              NUMBER(10)          NOT NULL,
    NOMBRE_ARCHIVO                  VARCHAR2(255)       NOT NULL, -- Nombre original proporcionado por el usuario (ej. 'examen_sangre_carmen.pdf')
    NOMBRE_ARCHIVO_ALMACENADO       VARCHAR2(255)       NOT NULL, -- Nombre con hash en disco (ej. 'a7f9b2c34d...9e.pdf')
    HASH_ARCHIVO                    VARCHAR2(128)       NOT NULL, -- Hash criptográfico (SHA-256 o MD5) para validación de integridad y deduplicación
    NOMBRE_DIRECTORIO_BD            VARCHAR2(128),                -- Directorio Oracle (DIRECTORY object de BD ej. 'DIR_ARCHIVOS_SAMANYA') para BFILE/UTL_FILE (puede ser nulo)
    RUTA_RELATIVA                   VARCHAR2(1000)      NOT NULL, -- Estructura de directorio dinámica (ej. '/centros/1/residentes/102/historias_clinicas/2026/09/')
    RUTA_COMPLETA_ALMACENAMIENTO    VARCHAR2(1500)      NOT NULL, -- URI o ruta física completa en el storage server
    EXTENSION                       VARCHAR2(20)        NOT NULL, -- '.pdf', '.jpg', '.png', '.docx'
    TIPO_MIME                       VARCHAR2(100)       NOT NULL, -- 'application/pdf', 'image/jpeg'
    TAMANO_BYTES                    NUMBER(14)          NOT NULL, -- Tamaño exacto en bytes
    ID_CLASE_ARCHIVO                NUMBER(10)          NOT NULL, -- Relación con SMY_CLASES_ARCHIVOS
    ID_CENTRO                       NUMBER(10),                   -- Relación con SMY_CENTROS (Jerarquía centro/sede)
    ID_RESIDENTE                    NUMBER(10),                   -- Relación con SMY_RESIDENTES (Jerarquía residente)
    ID_ESTADO_ARCHIVO               NUMBER(10)          DEFAULT 1 NOT NULL, -- Relación con SMY_ESTADOS_ARCHIVOS (1=Activo/Disponible, 2=Eliminado/Papelera, etc.)
    TABLA_ORIGEN                    VARCHAR2(50),                 -- Nombre de la tabla de negocio vinculada (ej. 'SMY_DOCUMENTOS_CLINICOS', 'SMY_CONSENTIMIENTOS')
    ID_REGISTRO_ORIGEN              NUMBER(10),                   -- ID del registro en la tabla de negocio
    METADATOS_JSON                  CLOB,                         -- Información adicional flexible en formato JSON nativo
    FECHA_ELIMINACION               DATE,                         -- Fecha en la cual el usuario marcó el archivo como eliminado (ID_ESTADO_ARCHIVO = 2)
    ID_USUARIO_ELIMINACION          NUMBER(10),                   -- Usuario que solicitó la eliminación
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    FECHA_ULTIMA_MODIFICACION       DATE,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_ARCHIVOS PRIMARY KEY (ID),
    CONSTRAINT UQ_SMY_ARC_ALMACENADO UNIQUE (NOMBRE_ARCHIVO_ALMACENADO),
    CONSTRAINT FK_SMY_ARC_CLASE FOREIGN KEY (ID_CLASE_ARCHIVO) REFERENCES SMY_CLASES_ARCHIVOS (ID),
    CONSTRAINT FK_SMY_ARC_CENTRO FOREIGN KEY (ID_CENTRO) REFERENCES SMY_CENTROS (ID),
    CONSTRAINT FK_SMY_ARC_RESIDENTE FOREIGN KEY (ID_RESIDENTE) REFERENCES SMY_RESIDENTES (ID),
    CONSTRAINT FK_SMY_ARC_ESTADO FOREIGN KEY (ID_ESTADO_ARCHIVO) REFERENCES SMY_ESTADOS_ARCHIVOS (ID)
);
CREATE SEQUENCE SEQ_SMY_ARCHIVOS START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_ARCHIVOS_BI
BEFORE INSERT ON SMY_ARCHIVOS FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_ARCHIVOS.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
    :NEW.FECHA_ULTIMA_MODIFICACION := CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE);
END;
/
CREATE OR REPLACE TRIGGER TRG_SMY_ARCHIVOS_BU
BEFORE UPDATE ON SMY_ARCHIVOS FOR EACH ROW
BEGIN
    :NEW.FECHA_ULTIMA_MODIFICACION := CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE);
    -- Si el estado cambia a Eliminado/Papelera (ID_ESTADO_ARCHIVO = 2), se audita el momento del borrado lógico
    IF :NEW.ID_ESTADO_ARCHIVO = 2 AND :OLD.ID_ESTADO_ARCHIVO <> 2 AND :NEW.FECHA_ELIMINACION IS NULL THEN
        :NEW.FECHA_ELIMINACION := CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE);
    END IF;
END;
/
COMMENT ON TABLE SMY_ARCHIVOS IS 'Repositorio de metadatos de archivos físicos almacenados en servidor externo o directorio Oracle con nombres hasheados y ciclo de vida por estados.';
COMMENT ON COLUMN SMY_ARCHIVOS.ID IS 'Identificador único y clave primaria de la tabla SMY_ARCHIVOS.';
COMMENT ON COLUMN SMY_ARCHIVOS.NOMBRE_ARCHIVO IS 'Nombre original con el que el usuario cargó el archivo (ej. cedula_carmen.pdf).';
COMMENT ON COLUMN SMY_ARCHIVOS.NOMBRE_ARCHIVO_ALMACENADO IS 'Nombre único del archivo en el servidor de archivos basado en hash criptográfico (ej. e3b0c442...pdf).';
COMMENT ON COLUMN SMY_ARCHIVOS.HASH_ARCHIVO IS 'Hash criptográfico (SHA-256) del contenido para verificación de integridad y prevención de duplicados.';
COMMENT ON COLUMN SMY_ARCHIVOS.NOMBRE_DIRECTORIO_BD IS 'Nombre del Directory Object de Oracle (DIRECTORIO de BD creado con CREATE DIRECTORY) en el que se ubica el archivo; puede ser nulo si el archivo se aloja exclusivamente en storage externo o nube.';
COMMENT ON COLUMN SMY_ARCHIVOS.RUTA_RELATIVA IS 'Ruta relativa de directorios dinámica calculada según centro, residente y clase de archivo.';
COMMENT ON COLUMN SMY_ARCHIVOS.RUTA_COMPLETA_ALMACENAMIENTO IS 'Ruta completa física o URI accesible por el servidor de almacenamiento.';
COMMENT ON COLUMN SMY_ARCHIVOS.EXTENSION IS 'Extensión normalizada del archivo (.pdf, .jpg, .png).';
COMMENT ON COLUMN SMY_ARCHIVOS.TIPO_MIME IS 'Tipo de contenido MIME del archivo (application/pdf, image/jpeg).';
COMMENT ON COLUMN SMY_ARCHIVOS.TAMANO_BYTES IS 'Tamaño total del archivo medido en bytes.';
COMMENT ON COLUMN SMY_ARCHIVOS.ID_CLASE_ARCHIVO IS 'Clave foránea hacia SMY_CLASES_ARCHIVOS.';
COMMENT ON COLUMN SMY_ARCHIVOS.ID_CENTRO IS 'Clave foránea hacia SMY_CENTROS (permite aislamiento y partición de archivos por sede).';
COMMENT ON COLUMN SMY_ARCHIVOS.ID_RESIDENTE IS 'Clave foránea hacia SMY_RESIDENTES (permite carpetas específicas por residente).';
COMMENT ON COLUMN SMY_ARCHIVOS.ID_ESTADO_ARCHIVO IS 'Clave foránea hacia SMY_ESTADOS_ARCHIVOS (1=Activo/Disponible, 2=Eliminado/Papelera, etc.); reemplaza banderas binarias permitiendo trazabilidad de ciclo de vida.';
COMMENT ON COLUMN SMY_ARCHIVOS.TABLA_ORIGEN IS 'Nombre de la tabla de negocio asociada para relación polimórfica (ej. SMY_DOCUMENTOS_CLINICOS).';
COMMENT ON COLUMN SMY_ARCHIVOS.ID_REGISTRO_ORIGEN IS 'ID del registro en la tabla de negocio asociada.';
COMMENT ON COLUMN SMY_ARCHIVOS.METADATOS_JSON IS 'Metadatos adicionales en formato JSON nativo (resolución, autor, escaneado, etc.).';
COMMENT ON COLUMN SMY_ARCHIVOS.FECHA_ELIMINACION IS 'Fecha y hora en que se ejecutó el borrado lógico (ID_ESTADO_ARCHIVO = 2).';
COMMENT ON COLUMN SMY_ARCHIVOS.ID_USUARIO_ELIMINACION IS 'Identificador del usuario que ordenó la eliminación del archivo.';
COMMENT ON COLUMN SMY_ARCHIVOS.FECHA_CREACION IS 'Fecha y hora de registro con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_ARCHIVOS.FECHA_ULTIMA_MODIFICACION IS 'Fecha y hora de la última modificación en base de datos.';
COMMENT ON COLUMN SMY_ARCHIVOS.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación.';

-- =============================================================================
-- SECCIÓN 5: MÓDULO DE BITÁCORA DIARIA Y SIGNOS VITALES
-- =============================================================================

-- Tabla: SMY_BITACORA_RESIDENTE
CREATE TABLE SMY_BITACORA_RESIDENTE (
    ID                              NUMBER(10)          NOT NULL,
    ID_RESIDENTE                    NUMBER(10)          NOT NULL,
    ID_EMPLEADO                     NUMBER(10),
    ID_USUARIO                      NUMBER(10)          NOT NULL,
    FECHA                           DATE                NOT NULL,
    HORA                            VARCHAR2(8)         NOT NULL, -- '08:30'
    ID_CATEGORIA_BITACORA           NUMBER(10)          NOT NULL,
    CONTENIDO                       CLOB                NOT NULL,
    GRABADO_POR_VOZ                 CHAR(1)             DEFAULT 'N' NOT NULL, -- 'S' / 'N'
    AUDIO_URL                       VARCHAR2(500),
    FOTO_ADJUNTA_URL                VARCHAR2(500),
    ID_TURNO_ASIGNADO               NUMBER(10),
    VISIBLE_ACUDIENTE               CHAR(1)             DEFAULT 'S' NOT NULL, -- 'S' / 'N'
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_BIT_RESIDENTE PRIMARY KEY (ID),
    CONSTRAINT FK_SMY_BIT_RESIDENTE FOREIGN KEY (ID_RESIDENTE) REFERENCES SMY_RESIDENTES (ID) ON DELETE CASCADE,
    CONSTRAINT FK_SMY_BIT_EMPLEADO FOREIGN KEY (ID_EMPLEADO) REFERENCES SMY_EMPLEADOS (ID),
    CONSTRAINT FK_SMY_BIT_USUARIO FOREIGN KEY (ID_USUARIO) REFERENCES SMY_USUARIOS (ID),
    CONSTRAINT FK_SMY_BIT_TURNO FOREIGN KEY (ID_TURNO_ASIGNADO) REFERENCES SMY_TURNOS_ASIGNADOS (ID),
    CONSTRAINT FK_SMY_BIT_CATEGORIA FOREIGN KEY (ID_CATEGORIA_BITACORA) REFERENCES SMY_CATEGORIAS_BITACORA (ID),
    CONSTRAINT CK_SMY_BIT_VOZ CHECK (GRABADO_POR_VOZ IN ('S', 'N')),
    CONSTRAINT CK_SMY_BIT_VIS_ACU CHECK (VISIBLE_ACUDIENTE IN ('S', 'N'))
);
CREATE SEQUENCE SEQ_SMY_BITACORA_RESIDENTE START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_BIT_RES_BI
BEFORE INSERT ON SMY_BITACORA_RESIDENTE FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_BITACORA_RESIDENTE.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_BITACORA_RESIDENTE
COMMENT ON TABLE SMY_BITACORA_RESIDENTE IS 'Registro cronológico continuo de novedades asistenciales, estado de ánimo y observaciones diarias.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.ID IS 'Identificador único y clave primaria de la tabla SMY_BITACORA_RESIDENTE.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.ID_RESIDENTE IS 'Clave foránea hacia SMY_RESIDENTES(ID) sobre el que se hace la anotación.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.ID_EMPLEADO IS 'Clave foránea que referencia al registro correspondiente a: empleado.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.ID_USUARIO IS 'Clave foránea que referencia al registro correspondiente a: usuario.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.FECHA IS 'Fecha calendario correspondiente a la novedad asistencial.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.HORA IS 'Hora del suceso en formato HH24:MI (ej. 10:30).';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.ID_CATEGORIA_BITACORA IS 'Clave foránea hacia SMY_CATEGORIAS_BITACORA(ID).';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.CONTENIDO IS 'Campo de datos para contenido en SMY_BITACORA_RESIDENTE.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.GRABADO_POR_VOZ IS 'Campo de datos para grabado por voz en SMY_BITACORA_RESIDENTE.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.AUDIO_URL IS 'Ruta de archivo de audio o nota de voz dictada por el cuidador.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.FOTO_ADJUNTA_URL IS 'Campo de datos para foto adjunta url en SMY_BITACORA_RESIDENTE.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.ID_TURNO_ASIGNADO IS 'Clave foránea que referencia al registro correspondiente a: turno asignado.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.VISIBLE_ACUDIENTE IS 'Campo de datos para visible acudiente en SMY_BITACORA_RESIDENTE.';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.FECHA_CREACION IS 'Fecha y hora de registro en base de datos con zona horaria legal de Bogotá (UTC-5).';
COMMENT ON COLUMN SMY_BITACORA_RESIDENTE.ID_USUARIO_ULTIMA_MODIFICACION IS 'Identificador del usuario que realizó la última modificación del registro.';

-- Tabla: SMY_SIGNOS_VITALES
CREATE TABLE SMY_SIGNOS_VITALES (
    ID                              NUMBER(10)          NOT NULL,
    ID_RESIDENTE                    NUMBER(10)          NOT NULL,
    ID_USUARIO_REGISTRO             NUMBER(10)          NOT NULL,
    FECHA                           DATE                NOT NULL,
    HORA                            VARCHAR2(8)         NOT NULL,
    PRESION_SISTOLICA               NUMBER(4),
    PRESION_DIASTOLICA              NUMBER(4),
    FRECUENCIA_CARDIACA             NUMBER(4),
    SATURACION_OXIGENO              NUMBER(5,2),
    TEMPERATURA                     NUMBER(4,2),
    GLUCOMETRIA                     NUMBER(5,2),
    PESO_KG                         NUMBER(5,2),
    OBSERVACIONES                   VARCHAR2(500),
    ES_ALERTA_RANGO                 CHAR(1)             DEFAULT 'N' NOT NULL, -- 'S' / 'N'
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_SIGNOS_VITALES PRIMARY KEY (ID),
    CONSTRAINT FK_SMY_SV_RESIDENTE FOREIGN KEY (ID_RESIDENTE) REFERENCES SMY_RESIDENTES (ID) ON DELETE CASCADE,
    CONSTRAINT FK_SMY_SV_USUARIO FOREIGN KEY (ID_USUARIO_REGISTRO) REFERENCES SMY_USUARIOS (ID),
    CONSTRAINT CK_SMY_SV_ALERTA CHECK (ES_ALERTA_RANGO IN ('S', 'N'))
);
CREATE SEQUENCE SEQ_SMY_SIGNOS_VITALES START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_SIGNOS_VIT_BI
BEFORE INSERT ON SMY_SIGNOS_VITALES FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_SIGNOS_VITALES.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_SIGNOS_VITALES
COMMENT ON TABLE SMY_SIGNOS_VITALES IS 'Monitoreo biomédico y registro de signos vitales (presión, FC, FR, glucosa, temperatura, SpO2).';
COMMENT ON COLUMN SMY_SIGNOS_VITALES.ID IS 'Identificador único y clave primaria de la tabla SMY_SIGNOS_VITALES.';
COMMENT ON COLUMN SMY_SIGNOS_VITALES.ID_RESIDENTE IS 'Clave foránea hacia SMY_RESIDENTES(ID) al que corresponden los signos.';
COMMENT ON COLUMN SMY_SIGNOS_VITALES.ID_USUARIO_REGISTRO IS 'Clave foránea que referencia al registro correspondiente a: usuario registro.';
COMMENT ON COLUMN SMY_SIGNOS_VITALES.FECHA IS 'Fecha calendario de la toma biomédica.';
COMMENT ON COLUMN SMY_SIGNOS_VITALES.HORA IS 'Hora de la medición en formato HH24:MI.';
COMMENT ON COLUMN SMY_SIGNOS_VITALES.PRESION_SISTOLICA IS 'Presión arterial sistólica en milímetros de mercurio (mmHg).';
