-- =============================================================================
-- SECCIÓN 6: MÓDULO DE FARMACOTERAPIA Y ADMINISTRACIÓN
-- =============================================================================

-- Tabla: SMY_MEDICAMENTOS_PRESCRITOS
CREATE TABLE SMY_MEDICAMENTOS_PRESCRITOS (
    ID                              NUMBER(10)          NOT NULL,
    ID_RESIDENTE                    NUMBER(10)          NOT NULL,
    NOMBRE_MEDICAMENTO              VARCHAR2(120)       NOT NULL,
    PRINCIPIO_ACTIVO                VARCHAR2(120),
    DOSIS                           VARCHAR2(50)        NOT NULL,
    CANTIDAD                        VARCHAR2(30),
    ID_VIA_ADMINISTRACION           NUMBER(10)          NOT NULL,
    FRECUENCIA_HORAS                NUMBER(4),
    HORARIOS_FIJOS                  VARCHAR2(100),
    INDICACIONES                    VARCHAR2(500),
    REQUIERE_FOTO_COMP              CHAR(1)             DEFAULT 'N' NOT NULL, -- 'S' / 'N'
    FECHA_INICIO                    DATE                NOT NULL,
    FECHA_FIN                       DATE,
    STOCK_ACTUAL                    NUMBER(6)           DEFAULT 0,
    STOCK_MINIMO                    NUMBER(6)           DEFAULT 5,
    ID_ESTADO_MEDICAMENTO           NUMBER(10)          NOT NULL,
    PRESCRITO_POR                   VARCHAR2(120),
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_MED_PRESCRITOS PRIMARY KEY (ID),
    CONSTRAINT FK_SMY_MP_RESIDENTE FOREIGN KEY (ID_RESIDENTE) REFERENCES SMY_RESIDENTES (ID) ON DELETE CASCADE,
    CONSTRAINT FK_SMY_MP_VIA FOREIGN KEY (ID_VIA_ADMINISTRACION) REFERENCES SMY_VIAS_ADMINISTRACION (ID),
    CONSTRAINT FK_SMY_MP_ESTADO FOREIGN KEY (ID_ESTADO_MEDICAMENTO) REFERENCES SMY_ESTADOS_MEDICAMENTOS (ID),
    CONSTRAINT CK_SMY_MP_FOTO CHECK (REQUIERE_FOTO_COMP IN ('S', 'N'))
);
CREATE SEQUENCE SEQ_SMY_MEDICAMENTOS_PRESCRITOS START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_MED_PRES_BI
BEFORE INSERT ON SMY_MEDICAMENTOS_PRESCRITOS FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_MEDICAMENTOS_PRESCRITOS.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_MEDICAMENTOS_PRESCRITOS
