COMMENT ON COLUMN SMY_CONSENTIMIENTO_DESTINATARIOS.FIRMA_DIGITAL_HASH IS 'Huella criptográfica (hash SHA-256) del acta firmada.';
COMMENT ON COLUMN SMY_CONSENTIMIENTO_DESTINATARIOS.FIRMA_IMAGEN_URL IS 'Ruta o URL del archivo PNG/WebP con el trazo de la firma manuscrita digital.';
