-- =============================================================================
-- SECCIÓN 11: MÓDULO DE INCIDENTES, EVENTOS ADVERSOS Y SEGUIMIENTO
-- =============================================================================

-- Tabla: SMY_INCIDENTES
CREATE TABLE SMY_INCIDENTES (
    ID                              NUMBER(10)          NOT NULL,
    ID_TIPO_INCIDENTE               NUMBER(10)          NOT NULL,
    ID_SEVERIDAD_INCIDENTE          NUMBER(10)          NOT NULL,
    FECHA_HORA_EVENTO               DATE                NOT NULL,
    DESCRIPCION                     CLOB                NOT NULL,
    ACCIONES_TOMADAS                CLOB,
    FOTO_EVIDENCIA_URL              VARCHAR2(500),
    ID_USUARIO_REPORTO              NUMBER(10)          NOT NULL,
    ID_ESTADO_INCIDENTE             NUMBER(10)          NOT NULL,
    NOTIFICADO_ACUDIENTE            CHAR(1)             DEFAULT 'S' NOT NULL, -- 'S' / 'N'
    FECHA_CIERRE                    DATE,
    ID_USUARIO_CERRO                NUMBER(10),
    CONCLUSIONES_CIERRE             CLOB,
    FECHA_CREACION                  DATE                DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE) NOT NULL,
    ID_USUARIO_ULTIMA_MODIFICACION  NUMBER(10),
    CONSTRAINT PK_SMY_INCIDENTES PRIMARY KEY (ID),
    CONSTRAINT FK_SMY_INC_TIPO FOREIGN KEY (ID_TIPO_INCIDENTE) REFERENCES SMY_TIPOS_INCIDENTES (ID),
    CONSTRAINT FK_SMY_INC_SEVERIDAD FOREIGN KEY (ID_SEVERIDAD_INCIDENTE) REFERENCES SMY_SEVERIDADES_INCIDENTES (ID),
    CONSTRAINT FK_SMY_INC_ESTADO FOREIGN KEY (ID_ESTADO_INCIDENTE) REFERENCES SMY_ESTADOS_INCIDENTES (ID),
    CONSTRAINT FK_SMY_INC_REPORTER FOREIGN KEY (ID_USUARIO_REPORTO) REFERENCES SMY_USUARIOS (ID),
    CONSTRAINT FK_SMY_INC_CERRADOR FOREIGN KEY (ID_USUARIO_CERRO) REFERENCES SMY_USUARIOS (ID),
    CONSTRAINT CK_SMY_INC_NOTIF CHECK (NOTIFICADO_ACUDIENTE IN ('S', 'N'))
);
CREATE SEQUENCE SEQ_SMY_INCIDENTES START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE OR REPLACE TRIGGER TRG_SMY_INCIDENTES_BI
BEFORE INSERT ON SMY_INCIDENTES FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN SELECT SEQ_SMY_INCIDENTES.NEXTVAL INTO :NEW.ID FROM DUAL; END IF;
END;
/
-- Comentarios del Diccionario de Datos: SMY_INCIDENTES
COMMENT ON TABLE SMY_INCIDENTES IS 'Registro institucional de eventos adversos, caídas e incidentes para gestión de calidad.';
COMMENT ON COLUMN SMY_INCIDENTES.ID IS 'Identificador único y clave primaria de la tabla SMY_INCIDENTES.';
